CREATE TABLE IF NOT EXISTS dm_company(id INTEGER PRIMARY KEY,symbol TEXT UNIQUE NOT NULL,isin TEXT NOT NULL,sector TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dm_metric(id INTEGER PRIMARY KEY,code TEXT NOT NULL,statement TEXT NOT NULL,UNIQUE(code,statement));
CREATE TABLE IF NOT EXISTS dm_period(id INTEGER PRIMARY KEY,start TEXT NOT NULL,end TEXT NOT NULL,kind TEXT NOT NULL,UNIQUE(start,end,kind));
CREATE TABLE IF NOT EXISTS dm_context(id INTEGER PRIMARY KEY,scope TEXT NOT NULL,dimensions TEXT NOT NULL,UNIQUE(scope,dimensions));
CREATE TABLE IF NOT EXISTS dm_unit(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS dm_filing(id INTEGER PRIMARY KEY,company_id INTEGER NOT NULL REFERENCES dm_company(id),url TEXT NOT NULL,sha TEXT NOT NULL,published TEXT,seq TEXT,endpoint TEXT NOT NULL,UNIQUE(company_id,url,sha));
CREATE TABLE IF NOT EXISTS ft_financials(id INTEGER PRIMARY KEY,company_id INTEGER NOT NULL REFERENCES dm_company(id),metric_id INTEGER NOT NULL REFERENCES dm_metric(id),period_id INTEGER NOT NULL REFERENCES dm_period(id),context_id INTEGER NOT NULL REFERENCES dm_context(id),unit_id INTEGER NOT NULL REFERENCES dm_unit(id),value_raw TEXT NOT NULL,status TEXT NOT NULL,UNIQUE(company_id,metric_id,period_id,context_id,unit_id,value_raw));
CREATE TABLE IF NOT EXISTS ft_source_reference(fact_id INTEGER REFERENCES ft_financials(id),filing_id INTEGER REFERENCES dm_filing(id),tag TEXT NOT NULL,decimals TEXT,PRIMARY KEY(fact_id,filing_id,tag));
CREATE TABLE IF NOT EXISTS ft_validation(filing_id INTEGER REFERENCES dm_filing(id),result TEXT NOT NULL,PRIMARY KEY(filing_id,result));
CREATE TABLE IF NOT EXISTS misc_etl_jobs(symbol TEXT,year INTEGER,route TEXT,state TEXT,detail TEXT,PRIMARY KEY(symbol,year,route));
CREATE TABLE IF NOT EXISTS misc_data_quarantine(filing_id INTEGER REFERENCES dm_filing(id),detail TEXT,PRIMARY KEY(filing_id,detail));
CREATE TABLE IF NOT EXISTS misc_schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO misc_schema_version VALUES(1);
CREATE VIEW IF NOT EXISTS vw_fund_observations AS SELECT f.id fact_id,c.symbol,c.sector,m.code metric_code,m.statement,p.start period_start,p.end period_end,p.kind period_type,x.scope consolidation,x.dimensions,u.name unit,f.value_raw,CASE WHEN u.name='INR' THEN CAST(f.value_raw AS REAL)/10000000 END value_crores,f.status FROM ft_financials f JOIN dm_company c ON c.id=f.company_id JOIN dm_metric m ON m.id=f.metric_id JOIN dm_period p ON p.id=f.period_id JOIN dm_context x ON x.id=f.context_id JOIN dm_unit u ON u.id=f.unit_id;
CREATE VIEW IF NOT EXISTS vw_fund_financial_revisions AS SELECT o.*,d.published,d.seq,d.url,d.sha FROM vw_fund_observations o JOIN ft_source_reference r ON r.fact_id=o.fact_id JOIN dm_filing d ON d.id=r.filing_id;
CREATE VIEW IF NOT EXISTS vw_fund_verified_financials AS SELECT * FROM vw_fund_observations WHERE status='INDEPENDENTLY_VERIFIED';
CREATE VIEW IF NOT EXISTS vw_fund_pnl_statement AS SELECT symbol,sector,period_start,period_end,period_type,consolidation,CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='BASIC_EPS' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='BASIC_EPS' THEN CAST(value_raw AS REAL) END) END AS basic_eps, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='DEPRECIATION' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='DEPRECIATION' THEN value_crores END) END AS depreciation, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='DILUTED_EPS' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='DILUTED_EPS' THEN CAST(value_raw AS REAL) END) END AS diluted_eps, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='EMPLOYEE_EXPENSE' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='EMPLOYEE_EXPENSE' THEN value_crores END) END AS employee_expense, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='EXPENSES_EX_PROVISIONS' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='EXPENSES_EX_PROVISIONS' THEN value_crores END) END AS expenses_ex_provisions, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='FEE_INCOME' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='FEE_INCOME' THEN value_crores END) END AS fee_income, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='FINANCE_COST' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='FINANCE_COST' THEN value_crores END) END AS finance_cost, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='INTEREST_EARNED' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='INTEREST_EARNED' THEN value_crores END) END AS interest_earned, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='MATERIAL_COST' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='MATERIAL_COST' THEN value_crores END) END AS material_cost, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='NET_PROFIT' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='NET_PROFIT' THEN value_crores END) END AS net_profit, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='OTHER_EXPENSE' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='OTHER_EXPENSE' THEN value_crores END) END AS other_expense, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='OTHER_INCOME' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='OTHER_INCOME' THEN value_crores END) END AS other_income, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='PBT' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='PBT' THEN value_crores END) END AS pbt, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='PROVISIONS' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='PROVISIONS' THEN value_crores END) END AS provisions, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='REVENUE' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='REVENUE' THEN value_crores END) END AS revenue, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='TAX' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='TAX' THEN value_crores END) END AS tax, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='TOTAL_EXPENSES' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='TOTAL_EXPENSES' THEN value_crores END) END AS total_expenses, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='TOTAL_INCOME' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='TOTAL_INCOME' THEN value_crores END) END AS total_income,'UNVERIFIED' quality_status FROM vw_fund_observations WHERE statement='PNL' AND dimensions='[]' AND status='CANDIDATE' GROUP BY symbol,sector,period_start,period_end,period_type,consolidation;
CREATE VIEW IF NOT EXISTS vw_fund_balance_sheet AS SELECT symbol,sector,period_start,period_end,period_type,consolidation,CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='ADVANCES' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='ADVANCES' THEN value_crores END) END AS advances, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='ASSETS' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='ASSETS' THEN value_crores END) END AS assets, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='BORROWINGS' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='BORROWINGS' THEN value_crores END) END AS borrowings, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='CAPITAL_RESERVES' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='CAPITAL_RESERVES' THEN value_crores END) END AS capital_reserves, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='CASH' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='CASH' THEN value_crores END) END AS cash, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='CURRENT_ASSETS' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='CURRENT_ASSETS' THEN value_crores END) END AS current_assets, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='CURRENT_BORROWINGS' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='CURRENT_BORROWINGS' THEN value_crores END) END AS current_borrowings, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='CURRENT_LIABILITIES' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='CURRENT_LIABILITIES' THEN value_crores END) END AS current_liabilities, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='DEBT_SECURITIES' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='DEBT_SECURITIES' THEN value_crores END) END AS debt_securities, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='DEPOSITS' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='DEPOSITS' THEN value_crores END) END AS deposits, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='EQUITY' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='EQUITY' THEN value_crores END) END AS equity, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='EQUITY_LIABILITIES' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='EQUITY_LIABILITIES' THEN value_crores END) END AS equity_liabilities, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='INVENTORY' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='INVENTORY' THEN value_crores END) END AS inventory, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='LIABILITIES' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='LIABILITIES' THEN value_crores END) END AS liabilities, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='LOANS' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='LOANS' THEN value_crores END) END AS loans, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='NONCURRENT_ASSETS' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='NONCURRENT_ASSETS' THEN value_crores END) END AS noncurrent_assets, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='NONCURRENT_BORROWINGS' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='NONCURRENT_BORROWINGS' THEN value_crores END) END AS noncurrent_borrowings, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='NONCURRENT_LIABILITIES' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='NONCURRENT_LIABILITIES' THEN value_crores END) END AS noncurrent_liabilities, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='RBI_CASH' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='RBI_CASH' THEN value_crores END) END AS rbi_cash, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='RECEIVABLES' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='RECEIVABLES' THEN value_crores END) END AS receivables,'UNVERIFIED' quality_status FROM vw_fund_observations WHERE statement='BS' AND dimensions='[]' AND status='CANDIDATE' GROUP BY symbol,sector,period_start,period_end,period_type,consolidation;
CREATE VIEW IF NOT EXISTS vw_fund_cash_flow AS SELECT symbol,sector,period_start,period_end,period_type,consolidation,CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='CAPEX' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='CAPEX' THEN value_crores END) END AS capex, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='CASH_BALANCE' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='CASH_BALANCE' THEN value_crores END) END AS cash_balance, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='CFF' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='CFF' THEN value_crores END) END AS cff, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='CFI' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='CFI' THEN value_crores END) END AS cfi, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='CFO' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='CFO' THEN value_crores END) END AS cfo, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='FX' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='FX' THEN value_crores END) END AS fx, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='NET_CHANGE' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='NET_CHANGE' THEN value_crores END) END AS net_change, CASE WHEN COUNT(DISTINCT CASE WHEN metric_code='NET_CHANGE_BEFORE_FX' THEN value_raw END)=1 THEN MAX(CASE WHEN metric_code='NET_CHANGE_BEFORE_FX' THEN value_crores END) END AS net_change_before_fx,'UNVERIFIED' quality_status FROM vw_fund_observations WHERE statement='CF' AND dimensions='[]' AND status='CANDIDATE' GROUP BY symbol,sector,period_start,period_end,period_type,consolidation;
CREATE VIEW IF NOT EXISTS vw_fund_banking_metrics AS SELECT * FROM vw_fund_observations WHERE sector='BANK';
CREATE VIEW IF NOT EXISTS vw_fund_annual_results AS SELECT * FROM vw_fund_pnl_statement WHERE period_type='ANNUAL';
CREATE VIEW IF NOT EXISTS vw_fund_quarterly_results AS SELECT * FROM vw_fund_pnl_statement WHERE period_type='QUARTERLY';
CREATE VIEW IF NOT EXISTS vw_fund_cross_sector_summary AS SELECT symbol,sector,period_end,consolidation,net_profit,total_income FROM vw_fund_pnl_statement;
